import { createBucket, put } from "@tigrisdata/storage";
import { readFile } from "fs/promises";

const RUN_ID_PATH = "/logs/artifacts/run-id";
const runIdRaw = (await readFile(RUN_ID_PATH, "utf-8")).trim();
const sourceBucketName = `harbor-isolation-${runIdRaw}`
  .toLowerCase()
  .replace(/[^a-z0-9.-]/g, "-");

console.log("Creating source bucket:", sourceBucketName);
const createResp = await createBucket(sourceBucketName, {
  enableSnapshot: true,
});
if (createResp.error) {
  // maybe already exists; ignore
  console.log("createBucket error (may already exist):", createResp.error.message ?? createResp.error);
} else {
  console.log("Bucket created:", JSON.stringify(createResp.data));
}

// Seed objects using the storage SDK put.
for (const key of ["seed1.txt", "seed2.txt"]) {
  const putResp = await put(sourceBucketName, key, `seed content for ${key}`, {
    contentType: "text/plain",
  });
  if (putResp.error) throw putResp.error;
  console.log(`Seeded ${key}`);
}
console.log("Setup complete.");

